package de.walahi.novosmp.clan;import de.walahi.novosmp.NovoSMPPlugin;import de.walahi.smpcore.commands.framework.BaseCommand;import org.bukkit.command.*;import org.bukkit.entity.Player;
public final class ClanChatCommand extends BaseCommand{private final ClanManager clans;public ClanChatCommand(NovoSMPPlugin p,ClanManager c){super(p);clans=c;}protected String permission(){return "smpcore.clan.use";}protected boolean execute(CommandSender s,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage("Nur für Spieler.");return true;}if(a.length==0){clans.reply(p,"/cc <Nachricht>");return true;}clans.clanChat(p,String.join(" ",a));return true;}}
